def normalize_sign(short_sign):
    return SIGN_MAP.get(short_sign, short_sign)

def get_astro_data(days_offset):
    target_date = datetime.now() + timedelta(days=days_offset)
    subject = AstrologicalSubjectFactory.from_birth_data(
        name="Future", year=target_date.year, month=target_date.month, day=target_date.day,
        hour=12, minute=0, lng=37.6173, lat=55.7558, tz_str="Europe/Moscow", online=False
    )
    return {
        "sun_sign": normalize_sign(subject.sun.sign),
        "moon_sign": normalize_sign(subject.moon.sign),
        "moon_position": subject.moon.position,
        "mercury_sign": normalize_sign(subject.mercury.sign),
        "mercury_retrograde": subject.mercury.retrograde,
        "venus_sign": normalize_sign(subject.venus.sign),
        "mars_sign": normalize_sign(subject.mars.sign),
        "date_str": target_date.strftime('%d.%m.%Y')
    }

def get_text_for_period(sign, period):
    sign_lower = sign.lower()
    day_of_year = datetime.now().timetuple().tm_yday
    week_num = datetime.now().isocalendar()[1]
    month_num = datetime.now().month
    
    if period == "today":
        idx = day_of_year % 5
        return {"focus": DAILY_TEXTS[sign_lower]['focus'][idx], "do": DAILY_TEXTS[sign_lower]['do'][idx], "avoid": DAILY_TEXTS[sign_lower]['avoid'][idx]}
    elif period == "tomorrow":
        idx = (day_of_year + 1) % 5
        return {"focus": DAILY_TEXTS[sign_lower]['focus'][idx], "do": DAILY_TEXTS[sign_lower]['do'][idx], "avoid": DAILY_TEXTS[sign_lower]['avoid'][idx]}
    elif period == "this_week":
        idx = week_num % 4
        return {"focus": "Недельный фокус", "do": WEEKLY_TEXTS[sign_lower][idx], "avoid": "Распыления на второстепенное"}
    elif period == "next_week":
        idx = (week_num + 1) % 4
        return {"focus": "Недельный фокус", "do": WEEKLY_TEXTS[sign_lower][idx], "avoid": "Спешки и суеты"}
    elif period == "this_month":
        idx = (month_num - 1) % 4
        return {"focus": "Месячная тема", "do": MONTHLY_TEXTS[sign_lower][idx], "avoid": "Отклонения от курса"}
    elif period == "next_month":
        idx = month_num % 4
        return {"focus": "Месячная тема", "do": MONTHLY_TEXTS[sign_lower][idx], "avoid": "Игнорирования деталей"}
    elif period == "this_year":
        return {"focus": "Годовая тема", "do": YEARLY_TEXTS[sign_lower], "avoid": "Отклонения от пути"}
    return {"focus": "", "do": "", "avoid": ""}

PERIODS = {"today": 0, "tomorrow": 1, "this_week": 7, "next_week": 14, "this_month": 30, "next_month": 60, "this_year": 365}
SIGNS = ['aries', 'taurus', 'gemini', 'cancer', 'leo', 'virgo', 'libra', 'scorpio', 'sagittarius', 'capricorn', 'aquarius', 'pisces']

horoscope = {}
for sign in SIGNS:
    sign_data = {}
    for period_name, days_offset in PERIODS.items():
        astro = get_astro_data(days_offset)
        texts = get_text_for_period(sign, period_name)
        
        # Русские названия для astro_fact
        sun_ru = SIGN_RU.get(astro['sun_sign'], astro['sun_sign'])
        moon_ru = SIGN_RU.get(astro['moon_sign'], astro['moon_sign'])
        mercury_ru = SIGN_RU.get(astro['mercury_sign'], astro['mercury_sign'])
        venus_ru = SIGN_RU.get(astro['venus_sign'], astro['venus_sign'])
        mars_ru = SIGN_RU.get(astro['mars_sign'], astro['mars_sign'])
        
        mercury_status = "ретроградный" if astro["mercury_retrograde"] else "прямой"
        astro_fact = (
            f"Солнце: {sun_ru} | "
            f"Луна: {moon_ru} | "
            f"Меркурий: {mercury_ru} ({mercury_status}) | "
            f"Венера: {venus_ru} | "
            f"Марс: {mars_ru}"
        )
        
        venus_text = VENUS_INTERPRETATIONS[astro['venus_sign']]
        mars_text = MARS_INTERPRETATIONS[astro['mars_sign']]
        
        avoid_text = texts['avoid']
        if astro["mercury_retrograde"] and period_name in ["today", "tomorrow"]:
            avoid_text += ". Меркурий ретроградный: перепроверяй документы."
        
        sign_data[period_name] = {
            "date_ref": astro["date_str"],
            "astro_fact": astro_fact,
            "venus": venus_text,
            "mars": mars_text,
            "focus": texts['focus'],
            "do": texts['do'],
            "avoid": avoid_text
        }
    horoscope[sign] = sign_data

today_astro = get_astro_data(0)
horoscope['meta'] = {
    'generated_at': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
    'current_moon': SIGN_RU.get(today_astro['moon_sign'], today_astro['moon_sign']),
    'current_mercury_rx': today_astro['mercury_retrograde']
}

with open('horoscope.json', 'w', encoding='utf-8') as f:
    json.dump(horoscope, f, ensure_ascii=False, indent=2)

